import{_ as t,o as l,c as e,a2 as s}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 7 章 计划模式与长任务执行","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 7 章 计划模式与长任务执行.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 7 章 计划模式与长任务执行.md"}'),n={name:"bluebook/第一篇 使用手册：先把我用起来/第 7 章 计划模式与长任务执行.md"};function o(i,a,r,d,p,h){return l(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="第-7-章-计划模式与长任务执行" tabindex="-1">第 7 章 计划模式与长任务执行 <a class="header-anchor" href="#第-7-章-计划模式与长任务执行" aria-label="Permalink to &quot;第 7 章 计划模式与长任务执行&quot;">​</a></h1><h2 id="_7-1-什么时候需要计划模式" tabindex="-1">7.1 什么时候需要计划模式 <a class="header-anchor" href="#_7-1-什么时候需要计划模式" aria-label="Permalink to &quot;7.1 什么时候需要计划模式&quot;">​</a></h2><p>小任务（写一段代码、改一个文件）不需要计划，直接干。但遇到这些情况，你应该让我<strong>先进计划模式</strong>：</p><ul><li>任务跨多个文件/多个步骤；</li><li>有顺序依赖（B 依赖 A 的结果）；</li><li>改的东西影响面大（重构、迁移）；</li><li>你希望先看到方案再决定动不动手。</li></ul><h2 id="_7-2-计划模式是什么体验" tabindex="-1">7.2 计划模式是什么体验 <a class="header-anchor" href="#_7-2-计划模式是什么体验" aria-label="Permalink to &quot;7.2 计划模式是什么体验&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：&quot;我想重构项目里的日志模块，先做个计划&quot;</span></span>
<span class="line"><span>我：进入计划模式</span></span>
<span class="line"><span>  → 只读：浏览代码结构、搜索相关调用（不动任何文件）</span></span>
<span class="line"><span>  → 分析：找出改动点、风险点、影响范围</span></span>
<span class="line"><span>  → 产出：一份实施计划（步骤、顺序、验收方式）</span></span>
<span class="line"><span>你：审阅计划，说&quot;执行&quot;或&quot;调整&quot;</span></span>
<span class="line"><span>我：退出计划模式，按计划逐步执行，每步报告进度</span></span></code></pre></div><p>关键特性：<strong>计划模式下我只读不改。</strong> 你看完方案再放行，避免我&quot;先斩后奏&quot;。</p><h2 id="_7-3-好计划长什么样" tabindex="-1">7.3 好计划长什么样 <a class="header-anchor" href="#_7-3-好计划长什么样" aria-label="Permalink to &quot;7.3 好计划长什么样&quot;">​</a></h2><p>一份值得放行的计划，包含：</p><table tabindex="0"><thead><tr><th>要素</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>步骤</td><td>拆成可执行的顺序步骤</td><td>1. 读现状 2. 改接口 3. 改调用方 4. 跑测试</td></tr><tr><td>顺序</td><td>明确依赖关系</td><td>第 4 步依赖第 2、3 步完成</td></tr><tr><td>风险</td><td>可能踩的坑</td><td>接口变更会影响 3 个模块</td></tr><tr><td>验收</td><td>每一步怎么算完成</td><td>测试通过、无回归</td></tr></tbody></table><h2 id="_7-4-执行中的进度管理" tabindex="-1">7.4 执行中的进度管理 <a class="header-anchor" href="#_7-4-执行中的进度管理" aria-label="Permalink to &quot;7.4 执行中的进度管理&quot;">​</a></h2><p>执行长任务时，我会：</p><ul><li>每完成一步，更新计划进度状态；</li><li>遇到偏离计划的情况，先说明再行动；</li><li>需要你决策的节点，停下来问你，不擅自做主。</li></ul><p>你可以随时打断：&quot;先停在第 2 步，我要看一下。&quot;</p><h2 id="_7-5-计划模式的纪律" tabindex="-1">7.5 计划模式的纪律 <a class="header-anchor" href="#_7-5-计划模式的纪律" aria-label="Permalink to &quot;7.5 计划模式的纪律&quot;">​</a></h2><ul><li>✅ 模式内不写文件，只读与规划；</li><li>✅ 计划要能被人看懂和审阅；</li><li>✅ 计划获批后才动手；</li><li>❌ 不要把计划模式当成&quot;拖延模式&quot;——目标仍然是尽快产出可验收的结果。</li></ul><h2 id="_7-6-练习" tabindex="-1">7.6 练习 <a class="header-anchor" href="#_7-6-练习" aria-label="Permalink to &quot;7.6 练习&quot;">​</a></h2><ol><li>给我一个中型任务（比如&quot;把 docs 目录整理成统一格式&quot;），要求先进计划模式。</li><li>审阅我给的计划，提出一处调整。</li><li>放行后观察：执行是否严格按步骤走？每步是否可检查？</li></ol><blockquote><p>小结：计划模式 = <strong>给重要任务加一道&quot;先想后做&quot;的闸门</strong>。改动越大，这道闸门越值钱。</p></blockquote>`,19)])])}const c=t(n,[["render",o]]);export{_ as __pageData,c as default};
